package com.coffee.management.organization.migration;

import static org.assertj.core.api.Assertions.assertThat;
import java.sql.*;import java.util.*;import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;
@Testcontainers(disabledWithoutDocker=true)
class OrganizationMigrationTest {
 @Container static final PostgreSQLContainer<?> POSTGRES=new PostgreSQLContainer<>("postgres:17-alpine").withDatabaseName("organization").withUsername("organization_migration").withPassword("test-only-password");
 @Test void createsOwnedTablesAndDatabaseSafeguards()throws Exception{Flyway.configure().dataSource(POSTGRES.getJdbcUrl(),POSTGRES.getUsername(),POSTGRES.getPassword()).locations("classpath:db/migration").load().migrate();try(Connection c=POSTGRES.createConnection("");Statement s=c.createStatement()){Set<String> tables=new TreeSet<>();try(ResultSet r=s.executeQuery("SELECT table_name FROM information_schema.tables WHERE table_schema='public'")){while(r.next())tables.add(r.getString(1));}assertThat(tables).contains("branches","employees","employee_assignments","schedules","schedule_entries","attendances","work_shifts","organization_outbox","organization_audit","organization_idempotency");s.execute("INSERT INTO branches(id,code,name,address,timezone,opens_at,closes_at,status) VALUES ('10000000-0000-0000-0000-000000000001','B01','Branch','Address','Asia/Bangkok','07:00','22:00','OPEN')");s.execute("INSERT INTO employees(id,identity_user_id,employee_code,full_name,hire_date,status) VALUES ('20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','E01','Employee','2026-01-01','ACTIVE')");s.execute("INSERT INTO work_shifts(id,branch_id,register_code,opened_by,opened_at,opening_cash,status) VALUES ('40000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','POS-1','30000000-0000-0000-0000-000000000001',CURRENT_TIMESTAMP,0,'OPEN')");assertThatThrownBySql(()->s.execute("INSERT INTO work_shifts(id,branch_id,register_code,opened_by,opened_at,opening_cash,status) VALUES ('40000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001','POS-1','30000000-0000-0000-0000-000000000001',CURRENT_TIMESTAMP,0,'OPEN')"));}}
 private static void assertThatThrownBySql(SqlAction a){org.assertj.core.api.Assertions.assertThatThrownBy(a::run).isInstanceOf(SQLException.class);} interface SqlAction{void run()throws SQLException;}
}
